@api_view(["POST"])
@authentication_classes([MtaIngestAuthentication])
@permission_classes([IsAuthenticated])
def inbound_webhook(request: Request) -> Response:
    serializer = InboundIngestSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    payload: dict[str, Any] = serializer.validated_data

    local_part = payload["alias"].strip().lower()
    sender_email = normalize_email_address(payload["sender"])
    message_id_hash = payload["message_id_hash"]

    # Uniform response for both "unknown alias" and "unverified sender" so a
    # probing attacker cannot enumerate live aliases by watching status codes.
    _dropped = Response({"status": "accepted"}, status=status.HTTP_202_ACCEPTED)

    try:
        alias = HouseholdInboxAlias.objects.select_related("family").get(
            local_part=local_part, status=HouseholdInboxAlias.Status.ACTIVE
        )
    except HouseholdInboxAlias.DoesNotExist:
        logger.warning("inbound_email.unknown_alias", extra={"local_part": local_part})
        return _dropped

    if not family_inbox_enabled_for_family(alias.family):
        logger.warning(
            "inbound_email.unsupported_family_alias",
            extra={"local_part": local_part, "family": str(alias.family.pk)},
        )
        return _dropped

    verified = VerifiedSender.objects.filter(
        family=alias.family,
        email_address__iexact=sender_email,
        verified_at__isnull=False,
    ).first()
    if verified is None:
        logger.warning(
            "inbound_email.unverified_sender",
            extra={"alias": local_part, "sender": sender_email},
        )
        return _dropped

    try:
        with transaction.atomic():
            message, created = InboundMessage.objects.get_or_create(
                alias=alias,
                message_id_hash=message_id_hash,
                defaults={
                    "verified_sender": verified,
                    "message_id": payload.get("message_id", ""),
                    "archive_key": payload["archive_key"],
                    "size_bytes": payload["size_bytes"],
                    "envelope_json": payload.get("envelope") or {},
                    "auth_results_json": payload.get("auth_results") or {},
                },
            )
    except IntegrityError:
        # Race on the (alias, message_id_hash) unique constraint — duplicate.
        message = InboundMessage.objects.get(
            alias=alias, message_id_hash=message_id_hash
        )
        created = False

    if created:
        # Import inside function to avoid pulling Celery into auth path.
        from inbound_email.tasks import parse_message

        # Small countdown gives object storage a moment of read-after-write
        # consistency between the MTA's PUT and the worker's GET.
        message_pk = str(message.pk)
        transaction.on_commit(
            lambda: parse_message.apply_async(args=[message_pk], countdown=2)
        )
        http_status: int = status.HTTP_201_CREATED
    else:
        logger.info("inbound_email.duplicate_message", extra={"hash": message_id_hash})
        http_status = status.HTTP_200_OK

    return Response(
        {
            "id": str(message.pk),
            "parse_status": message.parse_status,
            "duplicate": not created,
        },
        status=http_status,
    )


@api_view(["GET"])
@authentication_classes([InternalAliasCacheAuthentication])
@permission_classes([IsAuthenticated])
def alias_cache_snapshot(request: Request) -> Response:
    """Return ``{ aliases: [{local_part, senders: [email, ...]}] }``.

    MTA polls this on a short interval, holds it in memory, and uses it
    to fail fast at SMTP time before any data is transferred.
    """

    snapshot: list[dict[str, Any]] = []
    qs = (
        HouseholdInboxAlias.objects.filter(status=HouseholdInboxAlias.Status.ACTIVE)
        .filter(
            Q(family__group_type__type="IMMEDIATE") | Q(family__group_type__isnull=True)
        )
        .prefetch_related("family__verified_senders")
        .order_by("local_part")
    )
    for alias in qs:
        senders = [
            v.email_address.lower()
            for v in alias.family.verified_senders.all()
            if v.verified_at is not None
        ]
        snapshot.append({"local_part": alias.local_part, "senders": senders})

    return Response({"version": 1, "aliases": snapshot})


def _families_for_user(user: User) -> QuerySet[FamilyGroup]:
    return _active_families_for_user(user).filter(
        Q(group_type__type="IMMEDIATE") | Q(group_type__isnull=True)
    )


def _active_families_for_user(user: User) -> QuerySet[FamilyGroup]:
    return FamilyGroup.objects.filter(
        memberships__user=user, memberships__is_active=True
    ).distinct()


def _inbox_memberships_for_user(user: User) -> QuerySet[FamilyMembership]:
    return FamilyMembership.objects.filter(
        user=user,
        is_active=True,
    ).filter(
        Q(family__group_type__type="IMMEDIATE") | Q(family__group_type__isnull=True)
    )


class VerifiedSenderViewSet(viewsets.ModelViewSet[VerifiedSender]):
    """List, add, and remove verified senders for the caller's families.

    Adding a sender requires the address to already be verified on the
    caller's account, then marks it usable immediately. Legacy pending
    rows can still be completed through the public email-link endpoint.

    Gated by the ``inbound-email-user-flow`` OpenFeature flag. When the
    flag is off for the caller, the entire surface returns 404 so it's
    indistinguishable from a not-yet-deployed feature.
    """

    serializer_class = VerifiedSenderSerializer
    permission_classes = [IsAuthenticated]
    http_method_names = ["get", "post", "delete", "head", "options"]

    def initial(self, request: Request, *args: Any, **kwargs: Any) -> None:
        super().initial(request, *args, **kwargs)
        if not user_flow_enabled_for_user(cast(User, request.user)):
            from django.http import Http404

            raise Http404("Inbound-email user flow is not enabled for this account.")

    def get_queryset(self) -> QuerySet[VerifiedSender]:
        user = cast(User, self.request.user)
        return VerifiedSender.objects.filter(
            family__in=_families_for_user(user)
        ).select_related("family")

    def perform_create(self, serializer: Any) -> None:
        user = cast(User, self.request.user)

        family_id = self.request.data.get("family")
        if family_id:
            try:
                family = _active_families_for_user(user).get(pk=family_id)
            except FamilyGroup.DoesNotExist as exc:
                from rest_framework.exceptions import PermissionDenied

                raise PermissionDenied(
                    "Cannot manage senders for a family you don't belong to."
                ) from exc
        else:
            membership = (
                _inbox_memberships_for_user(user)
                .order_by("-is_admin", "joined_at")
                .first()
            )
            if membership is None:
                from rest_framework.exceptions import ValidationError

                raise ValidationError("User must belong to at least one family.")
            family = membership.family

        if not family_inbox_enabled_for_family(family):
            from rest_framework.exceptions import ValidationError

            raise ValidationError("Inbox is only available for an immediate family.")

        email = normalize_email_address(serializer.validated_data["email_address"])
        if not is_email_verified_for_user(user, email):
            from rest_framework.exceptions import ValidationError

            raise ValidationError(
                {
                    "email_address": [
                        "Use a verified email address on your ClanCal account."
                    ]
                }
            )

        # Cap per family to deter using one household as a relay for many.
        existing_count = VerifiedSender.objects.filter(
            family=family, verified_at__isnull=False
        ).count()
        cap = getattr(settings, "INBOUND_EMAIL_VERIFIED_SENDER_CAP", 8)
        if existing_count >= cap:
            from rest_framework.exceptions import ValidationError

            raise ValidationError(
                f"Family already has {cap} verified senders (the maximum)."
            )

        sender, _created = VerifiedSender.objects.get_or_create(
            family=family,
            email_address=email,
            defaults={"requested_by": user},
        )
        if sender.is_verified:
            # Idempotent re-add of an already-verified address.
            serializer.instance = sender
            return

        # Verified allauth ownership is the trust boundary here; keep the
        # stored sender immediately usable and rotate away any pending link.
        sender.verified_at = timezone.now()
        sender.verified_via = VerifiedSender.VerifiedVia.ACCOUNT_EMAIL
        sender.requested_by = user
        from inbound_email.models import generate_verification_token

        sender.verification_token = generate_verification_token()
        sender.save(
            update_fields=[
                "verified_at",
                "verified_via",
                "requested_by",
                "verification_token",
                "updated_at",
            ]
        )
        serializer.instance = sender

    @staticmethod
    def alias_for(family: FamilyGroup) -> HouseholdInboxAlias:
        alias, _ = HouseholdInboxAlias.objects.get_or_create(
            family=family,
            defaults={"local_part": generate_alias_local_part()},
        )
        return alias


@api_view(["GET"])
@authentication_classes([])
@permission_classes([])
def household_alias_detail(request: Request) -> Response:
    """Return the caller's primary family's alias address.

    Used by the mobile app to display ``h_xxx@inbox.clancal.com`` on the
    Inbox setup screen. Creates the alias on first access.
    """
    if not request.user.is_authenticated:
        return Response(
            {"detail": "auth required"}, status=status.HTTP_401_UNAUTHORIZED
        )
    user = request.user
    if not user_flow_enabled_for_user(user):
        # Mirror the ViewSet's 404 so feature presence isn't leakable.
        return Response({"detail": "not found"}, status=status.HTTP_404_NOT_FOUND)
    membership = (
        _inbox_memberships_for_user(user).order_by("-is_admin", "joined_at").first()
    )
    if membership is None:
        return Response(
            {"detail": "user has no active family"},
            status=status.HTTP_404_NOT_FOUND,
        )
    alias = VerifiedSenderViewSet.alias_for(membership.family)
    return Response(HouseholdInboxAliasSerializer(alias).data)


def verify_sender_link(request: HttpRequest, token: str) -> HttpResponse:
    """Public endpoint hit by the recipient clicking the confirmation link.

    No authentication: the unguessable token IS the credential. On match,
    flip ``verified_at`` and render a minimal success template (auto-escaped).
    """
    try:
        sender = VerifiedSender.objects.select_related("family").get(
            verification_token=token
        )
    except VerifiedSender.DoesNotExist:
        return render(request, "inbound_email/verify_invalid.html", status=404)

    if not user_flow_enabled_for_family(
        sender.family
    ) or not family_inbox_enabled_for_family(sender.family):
        # Defense-in-depth: if the flag was flipped off between send and
        # click, refuse the verification rather than half-enrolling the
        # address.
        return render(request, "inbound_email/verify_invalid.html", status=404)

    if sender.is_verified:
        return render(
            request,
            "inbound_email/verify_already.html",
            {
                "email_address": sender.email_address,
                "family_name": sender.family.name,
            },
        )

    sender.verified_at = timezone.now()
    sender.verified_via = VerifiedSender.VerifiedVia.EMAIL_LINK
    sender.save(update_fields=["verified_at", "verified_via", "updated_at"])

    alias = VerifiedSenderViewSet.alias_for(sender.family)
    domain = getattr(settings, "INBOUND_EMAIL_DOMAIN", "inbox.clancal.com")
    return render(
        request,
        "inbound_email/verify_success.html",
        {
            "alias_address": f"{alias.local_part}@{domain}",
            "email_address": sender.email_address,
            "family_name": sender.family.name,
        },
    )
